using NorthernLink.Compliance.Domain.RegulatoryBasis;

namespace NorthernLink.Compliance.Application.RegulatoryBasis;

/// <summary>
/// The regulatory-basis catalogue as seed data, from NL-SP-02's Legislative and Standards
/// Framework table and every "Regulatory basis" box in the plan. Quotations are verbatim from the
/// plan; plain explanations are written for a new hire; consequences appear where the plan states
/// one. Source URLs were verified against the current consolidations (2026-10); where the plan's
/// citation differs from the consolidation, <c>PlanCitationNote</c> carries the plan's wording so
/// NL-SP-02 can be corrected.
/// <para>
/// Upserted by key from <c>seed-defaults</c>. Keys are <see cref="BasisKeys"/> constants;
/// <c>RegulatoryBasisCoverageTests</c> proves the two lists agree and that every key an error or
/// a record type cites exists here.
/// </para>
/// </summary>
public static class RegulatoryBasisSeed
{
    private const string Mb = "CA-MB";
    private const string Ca = "CA";
    private const int Version = 1;
    private static readonly DateOnly Effective = new(2026, 10, 1);

    private const string Hta = "https://web2.gov.mb.ca/laws/statutes/ccsm/h060.php";
    private const string Mr132 = "https://web2.gov.mb.ca/laws/regs/current/132-2024.php";
    private const string Mr72 = "https://web2.gov.mb.ca/laws/regs/current/072-2007.php";
    private const string Mr95 = "https://web2.gov.mb.ca/laws/regs/current/095-2008.php";
    private const string Mr76 = "https://web2.gov.mb.ca/laws/regs/current/076-94.php";
    private const string Mr28 = "https://web2.gov.mb.ca/laws/regs/current/028-2019.php";
    private const string Mr31 = "https://web2.gov.mb.ca/laws/regs/current/031-2019.php";
    private const string Mr259 = "https://web2.gov.mb.ca/laws/regs/current/259-2014.php";
    private const string Mr89 = "https://web2.gov.mb.ca/laws/regs/current/089-2013.php";
    private const string Mr16 = "https://web2.gov.mb.ca/laws/regs/current/016-2019.php";
    private const string Mr37 = "https://web2.gov.mb.ca/laws/regs/current/037-2005.php";
    private const string Mr155 = "https://web2.gov.mb.ca/laws/regs/current/155-2018.php";
    private const string Sor2005 = "https://laws-lois.justice.gc.ca/eng/regulations/SOR-2005-313/";
    private const string Sor2001 = "https://laws-lois.justice.gc.ca/eng/regulations/SOR-2001-286/";
    private const string Nsc4Url = "https://www.ccmta.ca/web/default/files/PDF/National_Safety_Code_Standard_4_-_Driver_Licensing_Classification_-_January_2020.pdf";
    private const string Nsc6Url = "https://www.ccmta.ca/web/default/files/PDF/NSC-6%E2%80%93Standard-Determining-Driver-Fitness-in-Canada.pdf";
    private const string Nsc7Url = "https://www.ccmta.ca/web/default/files/PDF/Standard_7.pdf";
    private const string Nsc9Url = "https://www.ccmta.ca/web/default/files/PDF/NSC-English/National%20Safety%20Code%20Standard%209%20-%20Commercial%20Vehicle%20Drivers%20Hours%20of%20Service%20-%20February%202022%20-%20Final.pdf";
    private const string Nsc10Url = "https://www.ccmta.ca/web/default/files/PDF/NSC_Standard_10-_June_2013.pdf";
    private const string Nsc11Url = "https://www.ccmta.ca/web/default/files/PDF/NSC-English/CCMTA%20NSC%20Standard%2011%20-%20January%202020%20-%20ENG.pdf";
    private const string Nsc12Url = "https://www.ccmta.ca/en/national-safety-code";
    private const string Nsc13Url = "https://www.ccmta.ca/web/default/files/PDF/Standard_13_March_2009.pdf";
    private const string Nsc14Url = "https://www.ccmta.ca/web/default/files/PDF/Standard_14.pdf";
    private const string Nsc15Url = "https://www.ccmta.ca/web/default/files/PDF/Standard_15.pdf";

    private const string OosTenHours = "Out-of-service declaration of 10 hours (NL-SP-02 s. 4.6).";
    private const string OosEightHours = "Out-of-service until 8 consecutive hours of off-duty time have been taken (NL-SP-02 s. 4.6).";
    private const string OosSeventyTwoHours = "Out-of-service declaration of 72 hours (NL-SP-02 s. 4.6).";
    private const string FineOnConviction = "$500–$5,000 fine on conviction (HTA s. 317).";

    public static IReadOnlyList<RegulatoryBasisDefinition> All { get; } = Build();

    private static RegulatoryBasisDefinition Entry(
        string key, string jurisdiction, RegulatoryInstrument instrument, string citation, string title,
        string? quotation, string plain, string? consequence, string? url, string? planNote = null) =>
        new(key, jurisdiction, instrument, citation, title, quotation, plain, consequence, url, planNote, Effective, Version);

    private static RegulatoryBasisDefinition HtaEntry(string key, string citation, string title, string? quotation, string plain, string anchor, string? consequence = null, string? planNote = null) =>
        Entry(key, Mb, RegulatoryInstrument.HTA, citation, title, quotation, plain, consequence, $"{Hta}#{anchor}", planNote);

    private static RegulatoryBasisDefinition Nsc(string key, string citation, string title, string? quotation, string plain, string url, string? consequence = null, string? planNote = null) =>
        Entry(key, Ca, RegulatoryInstrument.NSC, citation, title, quotation, plain, consequence, url, planNote);

    private static RegulatoryBasisDefinition Mr(string key, string citation, string title, string? quotation, string plain, string url, string? planNote = null, string? consequence = null) =>
        Entry(key, Mb, RegulatoryInstrument.ManitobaRegulation, citation, title, quotation, plain, consequence, url, planNote);

    private static RegulatoryBasisDefinition Guidance(string key, RegulatoryInstrument instrument, string jurisdiction, string citation, string title, string plain, string url) =>
        Entry(key, jurisdiction, instrument, citation, title, null, plain, null, url);

    private static RegulatoryBasisDefinition Plan(string key, string section, string title, string plain) =>
        Entry(key, Mb, RegulatoryInstrument.SafetyPlan, $"NL-SP-02 s. {section}", title, null, plain, null, null);

    private static List<RegulatoryBasisDefinition> Build() =>
    [
        // ---- The Highway Traffic Act, C.C.S.M. c. H60 -------------------------------------------------
        HtaEntry(BasisKeys.HtaRegulatedVehicle, "s. 1(1) \"regulated vehicle\"", "The Highway Traffic Act, C.C.S.M. c. H60 — definition of regulated vehicle",
            "“‘regulated vehicle’ means, subject to the regulations, (a) a motor vehicle or trailer that has a registered gross weight of 4,500 kg or more, or (b) a bus;”",
            "Any truck or trailer registered at 4,500 kg or more, and any bus, is a regulated vehicle. Our shuttles are buses, so every motor-carrier rule in the Act applies to them.",
            "1"),
        HtaEntry(BasisKeys.HtaBus, "s. 1(1) \"bus\"", "The Highway Traffic Act, C.C.S.M. c. H60 — definition of bus",
            "“‘bus’ means a motor vehicle designed to carry 11 or more persons including the driver;”",
            "A vehicle built to carry 11 or more people, counting the driver, is a bus under the Act — whatever it is called on the lot.",
            "1"),
        HtaEntry(BasisKeys.Hta134_3, "s. 134(3)", "Stopping at uncontrolled railway crossings",
            "“(3) … a driver must also stop before proceeding across … (b) an uncontrolled railway crossing if the driver is driving (i) a bus carrying passengers for compensation …”",
            "A bus carrying paying passengers must stop at every railway crossing that has no gates or lights, even when the track looks clear.",
            "134(3)"),
        HtaEntry(BasisKeys.Hta134_4, "s. 134(4)", "Additional requirements for particular vehicles",
            "“(4) While a vehicle described in subsection (3) is stopped as required by subsection (2) or (3), the driver must (a) look in both directions along the railway track for an approaching railway train; (b) listen for signals indicating the approach of a railway train; and (c) if the vehicle is a bus or school bus, open the door of the vehicle.”",
            "At the crossing the driver looks both ways, listens, and on a bus opens the door before crossing.",
            "134(4)"),
        HtaEntry(BasisKeys.Hta155_2, "s. 155(2)", "Accident reports by drivers",
            "“(2) The driver of a vehicle that is involved in an accident must without delay give the information set out in subsection (3) to (a) the driver of any other vehicle involved in the accident; (b) any person who is injured in the accident; and (c) any person whose property is damaged as a result of the accident.”",
            "After a collision the driver must give their name, licence, vehicle and insurance details to the other driver and to anyone hurt or whose property was damaged.",
            "155(2)"),
        HtaEntry(BasisKeys.Hta155_5, "s. 155(5)", "Requirement to stop vehicle",
            "“(5) For greater certainty, a driver to whom subsection (2) or (4) applies is required to stop the vehicle at the place where the accident occurs for the purpose of complying with that subsection.”",
            "The driver has to stop at the scene to exchange that information — driving on and calling later is not allowed.",
            "155(5)"),
        HtaEntry(BasisKeys.Hta155_6, "s. 155(6)", "Police reports of certain accidents",
            "“(6) The driver of a vehicle that is involved in an accident must make a police report about the accident if (a) the driver, for any reason, did not or was not able to give a peace officer the information required by subsection (3) at the place of the accident; and (b) any of the criteria set out in subsection (7) apply in respect of the accident.”",
            "If police were not at the scene and the accident was serious enough (see s. 155(7)), the driver must go and make a police report.",
            "155(6)"),
        HtaEntry(BasisKeys.Hta155_7, "s. 155(7)", "Criteria for making a police report",
            "“(7) A police report must be made if the driver … is aware or has reason to believe at the time of the accident, or is later made aware, (a) that a person, including the first driver, was injured in the accident and was admitted to hospital for observation or treatment for the injury; (b) that a person injured in the accident has died; …”",
            "A police report is required when someone was taken to hospital or died — even if the driver only learns of it afterwards.",
            "155(7)"),
        HtaEntry(BasisKeys.Hta185_1_1, "s. 185.1(1)", "Safety measures for wheelchair-bound passengers",
            "“Except as permitted by the regulations, a driver must not drive a motor vehicle on a highway unless (a) every wheelchair or other mobility aid occupied by a person in the motor vehicle is properly secured with a securement device that meets the requirements of the regulations; and (b) every person occupying a wheelchair or other mobility aid in the motor vehicle is properly restrained by an occupant restraint system that meets the requirements of the regulations.”",
            "A passenger riding in a wheelchair must have the chair tied down with approved securements and wear an approved restraint before the vehicle moves.",
            "185.1"),
        HtaEntry(BasisKeys.Hta186_3, "s. 186(3)", "Driver must wear seat belt",
            "“(3) Except as permitted by the regulations, the driver of a motor vehicle that is being driven on a highway must wear, in a properly adjusted and securely fastened manner, the complete seat belt provided for the driver's seating position.”",
            "The driver wears the full seat belt, adjusted and fastened, whenever the vehicle is on the road.",
            "186(3)"),
        HtaEntry(BasisKeys.Hta186_4, "s. 186(4)", "Passengers must wear seat belts",
            "“(4) Except as permitted by the regulations, a passenger in a motor vehicle that is being driven on a highway must (a) be seated in a seating position for which a seat belt is provided; and (b) wear the complete seat belt in a properly adjusted and securely fastened manner.”",
            "Every passenger sits in a seat that has a belt and wears it. No standing and no sharing seats.",
            "186(4)"),
        HtaEntry(BasisKeys.Hta186_6, "s. 186(6)", "Driver must not drive if passenger not safely seated",
            "“(6) Except as permitted by the regulations, a driver must not drive a motor vehicle on a highway (a) unless every person in the motor vehicle who is younger than 18 years of age is wearing … the complete seat belt provided for the seating position in which the person is seated; … (c) if there are more persons in the motor vehicle than there are seating positions for which seat belts have been provided; or (d) if there are more seating positions in the motor vehicle than were provided by its manufacturer when it was originally manufactured.”",
            "The driver may not move until every passenger under 18 is belted, there are no more people than belted seats, and nobody has added seats the maker did not install.",
            "186(6)"),
        HtaEntry(BasisKeys.Hta186_9, "s. 186(9)", "Child restraining devices",
            "“No person shall drive a motor vehicle on a highway unless every passenger who is of an age, weight or height specified in the regulations is properly seated and restrained in a child restraining device as required by the regulations.”",
            "Small children ride in a proper car seat or booster — the regulation says who counts as small (see M.R. 89/2013).",
            "186(9)"),
        HtaEntry(BasisKeys.Hta215_1_2, "s. 215.1(2)", "Using hand-operated electronic device while driving prohibited",
            "“No person shall use a hand-operated electronic device while driving a vehicle on a highway unless, (a) before using the device by hand, the person safely drives the vehicle off the roadway and keeps the vehicle stationary while using the device; or (b) the device (i) is a cellular telephone or another electronic device that includes a telephone function, and (ii) is configured and equipped to allow hands-free use as a telephone and is used in a hands-free manner.”",
            "No phone in the hand while driving. Pull off the road and stop first, or use a hands-free setup for calls only.",
            "215.1(2)"),
        HtaEntry(BasisKeys.Hta265_1_1, "s. 265.1(1)", "Request for surrender of licence",
            "“(1) A peace officer who believes, on reasonable and probable grounds, that a driver of a regulated vehicle is in contravention of this Act or regulations respecting hours of service, shall request the driver to surrender their licence.”",
            "An officer who believes a driver has broken the hours-of-service rules will ask for the driver's licence on the spot.",
            "265.1",
            "Licence suspended at the roadside (s. 265.1(3))."),
        HtaEntry(BasisKeys.Hta265_1_3, "s. 265.1(3)", "Automatic suspension of licence",
            "“(3) Upon a request being made under subsection (1), whether or not the driver surrenders their licence to the peace officer, the driver's licence is suspended …”",
            "Once the officer asks for the licence it is suspended — handing it over or not makes no difference.",
            "265.1(3)",
            "Licence suspended at the roadside; the driver cannot continue the trip."),
        HtaEntry(BasisKeys.Hta312_1, "s. 312.1 \"motor carrier\"", "Definitions (Part 10) — motor carrier",
            "“‘motor carrier’ means a person who (a) owns a regulated vehicle, alone or together with another person, or is entitled to be its registered owner under The Drivers and Vehicles Act; (b) is engaged in an enterprise or activity as part of which a regulated vehicle is used for the transportation of persons or property (not including personal transportation), whether or not the regulated vehicle's use results in a specific gain or compensation; …”",
            "Northern Link is a motor carrier because it owns buses and uses them to move people and goods — paid or not.",
            "312.1"),
        HtaEntry(BasisKeys.Hta312_2_1, "s. 312.2(1)", "Safety fitness requirements for motor carriers",
            "“Unless a motor carrier holds a safety fitness certificate, the motor carrier must not (a) drive or operate a regulated vehicle on a highway or permit a regulated vehicle to be driven or operated on a highway; or (b) tow a regulated vehicle on a highway or permit a regulated vehicle to be towed on a highway.”",
            "No safety fitness certificate, no wheels on the road. The SFC is the licence to operate as a carrier.",
            "312.2",
            FineOnConviction),
        HtaEntry(BasisKeys.Hta312_2_7, "s. 312.2(7)(b)", "Director may refuse to issue safety fitness certificate",
            "“The director may refuse to issue a safety fitness certificate … (b) if the motor carrier does not hold the insurance coverage required by the regulations;”",
            "Without the required insurance the government can refuse the safety fitness certificate.",
            "312.2(7)"),
        HtaEntry(BasisKeys.Hta312_2_12, "s. 312.2(12)", "Driver to carry copy of certificate",
            "“The driver of a regulated vehicle operated under a safety fitness certificate must carry a copy of the safety fitness certificate and produce it on request of an inspector or other peace officer.”",
            "A copy of the SFC rides in every bus and is shown to any inspector or officer who asks.",
            "312.2(12)"),
        HtaEntry(BasisKeys.Hta312_3_2, "s. 312.3(2)", "Prohibition re out-of-service regulated vehicles",
            "“A person must not drive or tow a regulated vehicle that has been ordered out of service under clause (1)(c) on a highway, unless (a) the condition that gave rise to the order has been remedied; or (b) the vehicle is being towed to remove it from the highway or to bring it to a place to have it repaired.”",
            "A vehicle an inspector has put out of service stays parked until the problem is fixed, unless it is being towed to a shop.",
            "312.3(2)"),
        HtaEntry(BasisKeys.Hta312_3_3, "s. 312.3(3)", "Duty to cooperate",
            "“A motor carrier and the driver of a regulated vehicle must cooperate with an inspector or other peace officer conducting an inspection under subsection (1) and provide any assistance and information reasonably required to carry out the inspection.”",
            "At a roadside inspection the driver and the company cooperate and hand over what the inspector reasonably asks for.",
            "312.3(3)"),
        HtaEntry(BasisKeys.Hta312_4, "s. 312.4", "Notice requirement re insurance",
            "“If an insurance policy has been filed with the department for the purpose of supporting a safety fitness certificate under this Part, a cancellation, change or refusal to renew the policy is not effective unless the department is provided at least 15 days' notice.”",
            "The insurance behind the SFC cannot be cancelled or changed without 15 days' notice to the department.",
            "312.4"),
        HtaEntry(BasisKeys.Hta313_1, "s. 313(1)", "Bills of lading",
            "“Every person who transports goods for compensation by means of a vehicle on a highway must use a bill of lading that meets the requirements prescribed under the regulations.”",
            "Every paid shipment travels with a bill of lading that contains what the regulation requires (M.R. 16/2019).",
            "313"),
        HtaEntry(BasisKeys.Hta314, "s. 314", "Identification of motor carriers",
            "“A motor carrier must ensure that each of their regulated vehicles displays information that identifies the motor carrier in accordance with the regulations.”",
            "Every bus shows the carrier's name and NSC number on the outside, as the regulation prescribes (M.R. 132/2024 s. 9).",
            "314"),
        HtaEntry(BasisKeys.Hta317, "s. 317", "Contravention of Act by motor carrier or employee an offence",
            "“A motor carrier or an employee of a motor carrier who, in connection with the operation of a regulated vehicle, contravenes or counsels another person to contravene a provision of this Act, The Drivers and Vehicles Act or a regulation under either of them is guilty of an offence and, in addition to any other applicable penalty, is liable on conviction to a fine of not less than $500 or more than $5,000.”",
            "Breaking any of these rules — or telling someone else to — is an offence for the company and the employee.",
            "317",
            FineOnConviction),
        HtaEntry(BasisKeys.Hta317_1_1, "s. 317.1(1)", "Offences by shippers of property",
            "“A person who ships property on a regulated vehicle and who, in relation to the shipment, causes the motor carrier to contravene a provision of this Act or the regulations or the vehicle to be operated in contravention of a provision of this Act or the regulations also commits any offence with which the motor carrier or the driver of the vehicle may be charged due to the contravention.”",
            "A shipper who makes us break the rules (overweight, badly declared goods) commits the same offence we would.",
            "317.1"),
        HtaEntry(BasisKeys.Hta318_1_3, "s. 318.1(3)", "Continuing driver disclosure",
            "“A person engaged by a motor carrier to drive or tow a regulated vehicle must, within 30 days after the event, disclose in writing to the motor carrier (a) particulars of any traffic accident (i) about which a police report must be made under subsection 155(6), (ii) that resulted in a vehicle involved in the accident being towed from the scene of the accident, or (iii) that resulted in more than $2,000 of damage to any property involved in the accident; (b) convictions arising from the operation or having care or control of a motor vehicle …; and (c) a suspension, cancellation, prohibition or change in classification of the person's driver's licence or an out-of-province driving permit held by the person.”",
            "Within 30 days a driver must tell the company in writing about any reportable accident (police report, tow, or more than $2,000 damage), any driving conviction, and any change to their licence — in any vehicle, on or off duty.",
            "318.1(3)",
            null,
            "The plan's framework table cites s. 318.1 generally; subsection (1) is repealed — only (3) and (4) apply."),
        HtaEntry(BasisKeys.Hta318_1_4, "s. 318.1(4)", "Accident information to be provided to director",
            "“A motor carrier must, within 30 days after receiving particulars of an accident under clause (3)(a), provide those particulars in writing to a director.”",
            "Once a driver reports an accident, the company has 30 days to pass the particulars on to the director in writing.",
            "318.1(4)"),
        HtaEntry(BasisKeys.Hta318_2, "s. 318.2", "Safety inspections and reports by driver",
            "“A person must not drive or tow a regulated vehicle on a highway unless (a) every vehicle driven or towed has been inspected in accordance with the regulations; (b) reports have been prepared and submitted at the times and in the manner and to the persons prescribed by regulation; and (c) every vehicle driven or towed has been found to be in safe operating condition.”",
            "No trip starts until the vehicle has had its inspection, the report is done, and the vehicle was found safe.",
            "318.2"),
        HtaEntry(BasisKeys.Hta318_3_1, "s. 318.3(1)", "Drivers' hours of service",
            "“A person must not drive or tow a regulated vehicle on a highway in contravention of the regulations respecting permitted hours of service of drivers.”",
            "Drivers stay within the hours-of-service limits (M.R. 72/2007, adopting the federal regulation).",
            "318.3"),
        HtaEntry(BasisKeys.Hta318_3_2, "s. 318.3(2)", "Driver records",
            "“A person who drives or tows, or has driven or towed, a regulated vehicle on a highway must make and maintain the records respecting hours of service prescribed by the regulations.”",
            "Every driver keeps a record of duty status for every day they drive a regulated vehicle.",
            "318.3(2)"),
        HtaEntry(BasisKeys.Hta318_3_2_1, "s. 318.3(2.1)", "Driver to provide records to motor carrier",
            "“A person engaged by a motor carrier to drive or tow a regulated vehicle must, without delay, provide a copy of the records required under subsection (2) to the motor carrier in accordance with the regulations.”",
            "Those records go to the company promptly — the regulation sets the deadline (20 days under NSC 9 s. 85(1)).",
            "318.3(2.1)"),
        HtaEntry(BasisKeys.Hta318_4, "s. 318.4", "Safe operation",
            "“A person must not drive or tow a regulated vehicle on a highway unless (a) the driver has inspected the cargo to be transported and it appears to be secured in accordance with the regulations; (b) equipment forming part of or carried on the vehicle is firmly secured; (c) the entry into and exit from, including an emergency exit from, the vehicle are unobstructed; (d) all passenger exits, including emergency exits, from the vehicle are unobstructed; (e) property transported is secured or stored so as not to pose a risk of injury to the driver or a passenger by its falling, displacement or other movement.”",
            "Before moving: cargo checked and secured, equipment tied down, every door and emergency exit clear, and nothing stowed where it could fall on someone.",
            "318.4"),
        HtaEntry(BasisKeys.Hta318_5_1, "s. 318.5(1)", "Compliance officer",
            "“(1) A motor carrier must designate, in writing, an individual to serve as the motor carrier's compliance officer.”",
            "The company names one person in writing as its compliance officer.",
            "318.5"),
        HtaEntry(BasisKeys.Hta318_5_2, "s. 318.5(2)", "Duties (compliance officer)",
            "“(2) A compliance officer is responsible for promoting compliance by the motor carrier and the motor carrier's employees with this Act and the regulations.”",
            "That person's job is to make sure the company and its drivers follow the Act and the regulations.",
            "318.5(2)"),
        HtaEntry(BasisKeys.Hta318_6_1, "s. 318.6(1)", "Initial review of driving record by motor carrier",
            "“Before engaging a person to drive or tow a regulated vehicle, a motor carrier must (a) if the person holds a driver's licence, obtain the person's driving record from the registrar; … and must review the driving record and determine whether the person is fit to drive the vehicle.”",
            "Before hiring a driver the company pulls their driving record (abstract) and decides from it whether they are fit to drive.",
            "318.6"),
        HtaEntry(BasisKeys.Hta318_6_2, "s. 318.6(2)", "Review of driving record by motor carrier",
            "“During each 12-month period of a person's engagement to drive or tow a regulated vehicle, a motor carrier must (a) if the person holds a driver's licence, obtain the person's driving record from the registrar; … and must review the driving record and determine whether the person continues to be fit to drive the vehicle.”",
            "Every 12 months the company pulls a fresh abstract for each driver and re-decides whether they are still fit.",
            "318.6(2)"),
        HtaEntry(BasisKeys.Hta318_6_3, "s. 318.6(3)", "Record to be current",
            "“(3) A motor carrier must ensure that each record obtained under subsections (1) and (2) is current to a date not earlier than 30 days before it is obtained.”",
            "The abstract has to be fresh — no more than 30 days old when the company gets it.",
            "318.6(3)"),
        HtaEntry(BasisKeys.Hta318_6_4, "s. 318.6(4)", "Timing and record of review",
            "“(4) A motor carrier must, for each review conducted under subsection (1) or (2), (a) conduct the review within 30 days; and (b) make and maintain a record of the date of the review, the name of the individual who conducted the review and any other information prescribed in the regulations.”",
            "The review happens within 30 days of getting the abstract, and the company writes down who reviewed it and when.",
            "318.6(4)"),
        HtaEntry(BasisKeys.Hta318_7_1, "s. 318.7(1)", "Maintenance of vehicles",
            "“(1) A motor carrier must (a) maintain a regulated vehicle in safe operating condition in accordance with standards of safety and repair applicable to it prescribed by the regulations; and (b) ensure that no driver drives the vehicle on the motor carrier's behalf unless defects listed in a driver inspection or other report prescribed by the regulations have been remedied so as to comply with prescribed standards of safety and repair applicable to the vehicle.”",
            "The company keeps every bus in safe condition and does not let a driver take one out with an unrepaired defect from an inspection report.",
            "318.7"),
        HtaEntry(BasisKeys.Hta318_7_2, "s. 318.7(2)", "Manufacturers' notices",
            "“(2) On becoming aware of a notice of defect issued by the manufacturer of a regulated vehicle, a motor carrier that operates a vehicle of that type must, without delay, remedy the defect in accordance with the manufacturer's instructions.”",
            "When a recall notice arrives for one of our vehicle types, the fix is done right away, the way the manufacturer says.",
            "318.7(2)"),
        HtaEntry(BasisKeys.Hta318_7_3, "s. 318.7(3)", "Maintenance records to be kept",
            "“(3) A motor carrier must make and keep a record in accordance with the regulations of each action taken under subsections (1) and (2) with respect to the vehicle.”",
            "Every repair, maintenance job and recall fix is written down and kept.",
            "318.7(3)"),
        HtaEntry(BasisKeys.Hta318_8_1, "s. 318.8(1)", "Motor carrier records",
            "“(1) A motor carrier must keep the following records: (a) drivers' disclosures submitted under subsection 318.1(3); (b) inspection reports submitted under section 318.2; (c) records made and submitted under subsection 318.3(2); (d) designations under subsection 318.5(1); (e) driving records obtained under section 318.6; (f) records of actions taken under subsection 318.7(3); (g) other records that the regulations require the motor carrier to make and keep.”",
            "This is the list of records the company must keep: driver disclosures, inspection reports, hours-of-service records, the compliance-officer designation, abstracts, maintenance records, and anything else the regulations name.",
            "318.8"),
        HtaEntry(BasisKeys.Hta318_8_2, "s. 318.8(2)", "Records must be accessible",
            "“(2) The motor carrier must ensure that the records described in subsection (1) are accessible in the same place, which must be either the motor carrier's chief place of business in Manitoba or another place approved by the minister.”",
            "All of those records must be reachable from one place — our chief place of business in Manitoba.",
            "318.8(2)"),
        HtaEntry(BasisKeys.Hta318_9, "s. 318.9", "Motor carrier to ensure driver compliance",
            "“A motor carrier must ensure that a driver who drives or tows a regulated vehicle on the motor carrier's behalf complies with sections 318.2 to 318.4.”",
            "The company is responsible for its drivers doing their inspections, keeping their hours and securing their loads — not just the driver.",
            "318.9"),
        HtaEntry(BasisKeys.Hta318_10_2, "s. 318.10(2)", "Powers of investigation",
            "“To ensure compliance with this Act, The Drivers and Vehicles Act and the regulations under either of those Acts, an inspector or a person authorized in writing by the minister may without a warrant and upon presentation on request of identification at the time of entry (a) subject to subsections (3) and (4), enter the premises of a person at any reasonable time for the purpose of carrying out an inspection, audit or examination of the records of a motor carrier; (b) require the production for inspection, audit or examination of all records required to be kept by the motor carrier under this Act or the regulations …”",
            "An inspector can come to the office in business hours, without a warrant, and ask to see any record we are required to keep.",
            "318.10(2)"),
        HtaEntry(BasisKeys.Hta322_1_3, "s. 322.1(3)", "Safety and compliance measures",
            "“If, after conducting a review, in accordance with the regulations, of a motor carrier's record maintained under subsection (1), a director … is of the opinion that it is reasonably necessary to prevent the motor carrier from operating in an unsafe manner, the director may do one or more of the following: (a) order the motor carrier to do such things as the director considers reasonably necessary to improve compliance …; (b) adjust the motor carrier's safety fitness rating; (c) suspend or revoke the motor carrier's safety fitness certificate; (d) impose a monetary penalty of not more than $25,000 on the motor carrier.”",
            "If our carrier profile shows unsafe operation, the director can order fixes, lower our safety rating, suspend or revoke the SFC, or fine the company.",
            "322.1(3)",
            "The director may suspend or revoke the SFC and impose a penalty of up to $25,000 (s. 322.1(3))."),
        HtaEntry(BasisKeys.Hta322_1_11, "s. 322.1(11)", "Prohibition on operating when safety fitness rating unsatisfactory",
            "“A motor carrier must not operate a regulated vehicle in Manitoba if the motor carrier has an unsatisfactory safety fitness rating under this section.”",
            "An unsatisfactory safety rating means the company cannot run any regulated vehicle in Manitoba.",
            "322.1(11)",
            "Operations stop until the rating is restored."),

        // ---- Manitoba regulations ---------------------------------------------------------------------
        Mr(BasisKeys.Mr132_2024, "M.R. 132/2024", "Regulated Vehicles and Motor Carriers Regulation", null,
            "The regulation under the Act that sets out the safety fitness certificate process, the insurance a carrier must hold and how vehicles are identified.",
            Mr132),
        Mr(BasisKeys.Mr132_2024_7_1_b, "M.R. 132/2024 s. 7(1)(b)", "Regulated Vehicles and Motor Carriers Regulation — insurance for buses", null,
            "Each bus used to carry passengers for compensation must be insured for third-party liability of at least $2,000,000.",
            Mr132,
            "The plan cites M.R. 132/2024 generally for insurance; the $2,000,000 bus minimum is s. 7(1)(b)."),
        Mr(BasisKeys.Mr132_2024_9, "M.R. 132/2024 s. 9", "Regulated Vehicles and Motor Carriers Regulation — carrier identification", null,
            "Every regulated vehicle displays the carrier's name or mark and its NSC number, as this section prescribes.",
            Mr132,
            "The plan cites M.R. 132/2024 generally for vehicle identification; the rule is s. 9."),
        Mr(BasisKeys.Mr72_2007, "M.R. 72/2007", "Drivers Hours of Service Regulation", null,
            "Manitoba's hours-of-service regulation adopts the federal Commercial Vehicle Drivers Hours of Service Regulations (SOR/2005-313), as amended, for all Manitoba motor carriers; s. 1(2) excludes federal ss. 3, 37–61 and 65.",
            Mr72,
            "The regulation applies to all Manitoba motor carriers — it is not worded as an intra-provincial regime."),
        Mr(BasisKeys.Mr95_2008, "M.R. 95/2008", "Commercial Vehicle Trip Inspection Regulation", null,
            "Manitoba's trip inspection regulation: daily inspections for all commercial vehicles, with the bus schedule, the motorcoach interval and what the report must record.",
            Mr95),
        Mr(BasisKeys.Mr95_2008_7_3, "M.R. 95/2008 s. 7(3) and Schedule B", "Commercial Vehicle Trip Inspection Regulation — bus inspection", null,
            "A bus is inspected every 24 hours against Schedule B (the bus schedule). Section 7 covers daily inspections for all vehicles; s. 8 is the motorcoach 30-day / 12,000 km inspection.",
            Mr95,
            "The plan cites 's. 7 bus schedule'; the bus rule is s. 7(3) with Schedule B."),
        Mr(BasisKeys.Mr95_2008_12_1, "M.R. 95/2008 s. 12(1)(a)(v)", "Commercial Vehicle Trip Inspection Regulation — report contents", null,
            "The trip inspection report must record where the inspection was done, among the other required items.",
            Mr95,
            "Not cited in the plan; added because the report form must carry the location."),
        Mr(BasisKeys.Mr76_94, "M.R. 76/94", "Periodic Mandatory Vehicle Inspection Regulation", null,
            "Manitoba's PMVI regulation: how often each class of vehicle gets its periodic safety inspection and what the certificate means.",
            Mr76),
        Mr(BasisKeys.Mr76_94_3_2_a_i, "M.R. 76/94 ss. 3(2)(a)(i), 5(2)(a)(i)", "Periodic Mandatory Vehicle Inspection Regulation — 6-month interval for buses", null,
            "A bus used to carry passengers for compensation is inspected every 6 months.",
            Mr76,
            "The plan cites M.R. 76/94 generally; the 6-month bus interval is ss. 3(2)(a)(i) and 5(2)(a)(i)."),
        Mr(BasisKeys.Mr28_2019, "M.R. 28/2019", "Standards for Mobility Aid Securement Devices and Occupant Restraint Systems and Related Exemptions Regulation", null,
            "The standards a wheelchair tie-down and its passenger restraint must meet (HTA s. 185.1).",
            Mr28,
            "The plan calls it the 'Mobility Aid Securement Regulation'; use the full title."),
        Mr(BasisKeys.Mr31_2019, "M.R. 31/2019", "Vehicle Equipment, Safety and Inspection Regulation", null,
            "The equipment every vehicle must have — including which buses need seat belts at which seats.",
            Mr31),
        Mr(BasisKeys.Mr31_2019_2_4_27, "M.R. 31/2019 s. 2.4, item 27", "Vehicle Equipment, Safety and Inspection Regulation — bus seat belts",
            "“… for the driver's seat if the bus was manufactured on or after January 1, 1971 … for each passenger seat if the bus was manufactured on or after September 1, 2020, unless the bus is (i) a school bus, or (ii) a perimeter-seating bus, prison bus or transit bus …”",
            "Buses built from 1971 need a driver's belt; buses built from September 2020 need a belt at every passenger seat (school and transit buses excepted).",
            Mr31,
            "The plan cites 's. 2.4(1) item 27'; s. 2.4 has no subsections — cite 's. 2.4, item 27'."),
        Mr(BasisKeys.Mr259_2014, "M.R. 259/2014", "Seat Belt Exemptions and Other Seating-Related Exemptions Regulation", null,
            "Who is excused from the seat-belt rules, and when.",
            Mr259),
        Mr(BasisKeys.Mr259_2014_5_2, "M.R. 259/2014 ss. 5(2)(g), 6(1)(d), 6(2)(d)", "Seat Belt Exemptions Regulation — vehicles not required to have belts",
            "“[s. 5(2)] … (g) a passenger being transported in a motor vehicle that is not required to be equipped with seat belts … under the Vehicle Equipment, Safety and Inspection Regulation; [ss. 6(1) and 6(2)] … (d) the driver of a motor vehicle that is not required to be equipped with seat belts … under the Vehicle Equipment, Safety and Inspection Regulation;”",
            "If the law did not require the bus to have belts at a seat, the passenger in that seat (and the driver of such a vehicle) is exempt — but where belts are fitted, they are worn.",
            Mr259),
        Mr(BasisKeys.Mr89_2013, "M.R. 89/2013", "Child Restraining Devices Regulation", null,
            "Which children must ride in a car seat or booster, and which vehicles are exempt.",
            Mr89),
        Mr(BasisKeys.Mr89_2013_5_1, "M.R. 89/2013 ss. 5(1), 9(g)", "Child Restraining Devices Regulation — who needs a child seat",
            "“[s. 5(1)] … (a) the passenger is less than nine years of age; (b) the passenger weighs less than 36 kg; (c) the passenger stands less than 145 cm tall. [s. 9] … (g) to a motor vehicle that is not required to be equipped with seat belts by the Motor Vehicle Safety Regulations.”",
            "A child under 9, under 36 kg or under 145 cm needs a child seat — except in a vehicle that is not required to have seat belts.",
            Mr89),
        Mr(BasisKeys.Mr16_2019, "M.R. 16/2019", "Bills of Lading and Uniform Conditions of Carriage Regulation", null,
            "What a bill of lading must contain and the standard conditions of carriage that are read into every one.",
            Mr16),
        Mr(BasisKeys.Mr16_2019_2_1, "M.R. 16/2019 s. 2(1)(a)–(q)", "Bills of Lading Regulation — required contents", null,
            "Section 2(1)(a) to (q) lists every item a bill of lading must show; s. 2(2) deems the Schedule A uniform conditions part of it.",
            Mr16),
        Mr(BasisKeys.Mr37_2005, "M.R. 37/2005", "Cargo Securement Regulation", null,
            "Manitoba's cargo securement rules (adopting NSC Standard 10): how loads are contained and tied down.",
            Mr37,
            "The plan cites the 'Securement of Vehicle Loads Regulation' (M.R. 157/91), which is repealed; the current instrument is the Cargo Securement Regulation, M.R. 37/2005."),
        Mr(BasisKeys.Mr155_2018, "M.R. 155/2018", "Vehicle Weights and Dimensions on Classes of Highways Regulation", null,
            "The weight and size limits a loaded vehicle must stay within on each class of highway.",
            Mr155),

        // ---- Federal regulations ----------------------------------------------------------------------
        Entry(BasisKeys.Sor2005_313, Ca, RegulatoryInstrument.FederalRegulation, "SOR/2005-313", "Commercial Vehicle Drivers Hours of Service Regulations", null,
            "The federal hours-of-service regulation. Manitoba adopts it through M.R. 72/2007, so its sections are the ones NSC Standard 9 and our HOS engine follow.",
            null, Sor2005),
        Entry(BasisKeys.Sor2005_313_85_3, Ca, RegulatoryInstrument.FederalRegulation, "SOR/2005-313 s. 85(3)", "Commercial Vehicle Drivers Hours of Service Regulations — carrier retention of RODS", null,
            "The carrier files records of duty status at its principal place of business within 30 days of receiving them and keeps them, in order, for at least 6 months (the federal text behind NSC 9 s. 85(3)).",
            null, Sor2005),
        Entry(BasisKeys.Sor2001_286, Ca, RegulatoryInstrument.FederalRegulation, "SOR/2001-286", "Transportation of Dangerous Goods Regulations", null,
            "The federal dangerous-goods rules — relevant when a parcel or cargo item is a regulated dangerous good.",
            null, Sor2001),

        // ---- National Safety Code -------------------------------------------------------------------
        Nsc(BasisKeys.Nsc4, "NSC Standard 4 (Jan 2020)", "Driver Licensing Classification", null,
            "The national licence classes. A bus with more than 24 passengers needs a Class 2; otherwise Class 4 or higher.",
            Nsc4Url),
        Nsc(BasisKeys.Nsc6, "NSC Standard 6 (Jun 2026)", "Determining Driver Fitness in Canada", null,
            "The national medical standards a commercial driver must meet to be fit to drive.",
            Nsc6Url),
        Nsc(BasisKeys.Nsc7, "NSC Standard 7 (Nov 2002)", "Carrier and Driver Profiles",
            "“The Profile system was established to provide NSC administrators with an overview of a carrier's record … The Profile system encompasses a wide range of components from carrier demographics, conviction information, reportable accident information, CVSA inspection information, audit results and monitoring activity …”",
            "The government keeps a running file on each carrier — convictions, accidents, roadside inspections, audits. That file decides our safety rating.",
            Nsc7Url),
        Nsc(BasisKeys.Nsc9, "NSC Standard 9 (Feb 2022)", "Commercial Vehicle Drivers Hours of Service", null,
            "The national hours-of-service standard. Its sections are quoted individually below.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc9_1_OnDutyTime, "NSC 9 s. 1 \"on-duty time\" (b)", "Hours of Service — personal use excluded from on-duty time",
            "“(b) does not include driving time for the driver's personal use if (i) the vehicle is not used in the course of the business of the motor carrier; (ii) the vehicle has been unloaded; (iii) any trailers have been unhitched; (iv) the distance travelled does not exceed 75 km in a day; (v) the driver has recorded in the daily log or record of duty status the odometer reading at the beginning and end of the personal use, and (vi) the driver is not the subject of an out-of-service declaration under section 91 or section 108.”",
            "Driving the empty bus for personal reasons does not count as work — up to 75 km a day, with the odometer written down at the start and end, and only if the driver is not out of service.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc9_4, "NSC 9 s. 4", "Hours of Service — general prohibition",
            "“No motor carrier, shipper, consignee or other person shall request, require or allow a driver to drive and no driver shall drive if: … (b) driving would be likely to jeopardize the safety or health of the public, the driver or the employees of the motor carrier; (c) the driver is the subject of an out-of-service declaration; or (d) the driver, in doing so, would not be in compliance with this Standard.”",
            "Nobody — dispatcher, client or driver — may put a driver on the road when it would be unsafe, when the driver is out of service, or when it would break the hours rules.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc9_12, "NSC 9 s. 12(1)-(2)", "Hours of Service — daily driving and on-duty limits",
            "“(1) No motor carrier shall request, require or allow a driver to drive and no driver shall drive after the driver has accumulated 13 hours of driving time in a day. (2) No motor carrier shall request, require or allow a driver to drive and no driver shall drive after the driver has accumulated 14 hours of on-duty time in a day.”",
            "In one day a driver may drive at most 13 hours and may not drive after 14 hours of work of any kind.",
            Nsc9Url,
            OosTenHours,
            "The plan cites this as 'NSC 9 s. 12.1'; the limits are s. 12(1) and (2)."),
        Nsc(BasisKeys.Nsc9_13_3, "NSC 9 s. 13(3)", "Hours of Service — 16-hour shift window",
            "“No motor carrier shall request, require or allow a driver to drive and no driver shall drive after 16 hours of time have elapsed between the conclusion of the most recent period of 8 or more consecutive hours of off-duty time and the beginning of the next period of 8 or more consecutive hours of off-duty time.”",
            "Once a driver's shift started (after 8 hours off), no driving after 16 clock hours have passed — breaks included.",
            Nsc9Url,
            OosTenHours),
        Nsc(BasisKeys.Nsc9_14, "NSC 9 s. 14(1)-(2)", "Hours of Service — daily off-duty time",
            "“(1) A motor carrier shall ensure that a driver takes, and the driver shall take at least 10 hours of off-duty time in a day. (2) Off-duty time other than the mandatory 8 consecutive hours may be distributed throughout the day in blocks of no less than 30 minutes each.”",
            "Every day has at least 10 hours off: 8 in one block, and the other 2 in pieces of at least 30 minutes.",
            Nsc9Url,
            OosEightHours),
        Nsc(BasisKeys.Nsc9_25_26, "NSC 9 ss. 25–26", "Hours of Service — 24 hours off in 14 days; Cycle 1 70 hours in 7 days",
            "“25 … no motor carrier shall request, require or allow a driver to drive and no driver shall drive unless the driver has taken at least 24 consecutive hours of off-duty time in the preceding 14 days. 26 … no motor carrier shall request, require or allow a driver who is following cycle 1 to drive, and no driver who is following cycle 1 shall drive, after the driver has accumulated 70 hours of on-duty time during any period of 7 days.”",
            "A driver needs a full 24 hours off at least once every 14 days, and on Cycle 1 may not drive after 70 hours of work in any 7 days.",
            Nsc9Url,
            OosSeventyTwoHours),
        Nsc(BasisKeys.Nsc9_76, "NSC 9 s. 76(2), (4)", "Hours of Service — adverse driving conditions",
            "“(2) A driver who encounters adverse driving conditions while driving the vehicle during a trip south of latitude 60°N may extend the permitted 13 hours of driving time specified in sections 12 and 13 and reduce the 2 hours of daily off-duty time required by subsection 14(3) by the amount of time needed to complete the trip if: (a) the driving, on-duty and elapsed time in the cycle the driver followed is not extended more than 2 hours; (b) the driver still takes the required 8 consecutive hours of off-duty time; and (c) the trip could have been completed under normal driving conditions without the reduction. … (4) A driver who extends their driving, on-duty or elapsed time because of an emergency or adverse driving conditions shall record the reason for doing so in the record of duty status …”",
            "Bad weather or road conditions the driver could not have known about allow up to 2 extra hours to finish the trip — the 8-hour block still stands, and the reason is written in the log.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc9_77_1, "NSC 9 s. 77(1)", "Hours of Service — ELD required",
            "“A motor carrier shall ensure that each commercial vehicle that it operates is equipped with an ELD that meets the requirements of the Technical Standard, and shall ensure that it is mounted in a fixed position during the operation of the commercial vehicle and is visible to the driver when the driver is in the normal driving position …”",
            "Every bus has a certified electronic logging device, mounted where the driver can see it.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc9_77_7, "NSC 9 s. 77(7)", "Hours of Service — ELD information packet", null,
            "Each vehicle carries the current ELD information packet (user instructions, malfunction instructions, blank paper logs); superseded versions are kept for 6 months.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc9_78_5, "NSC 9 s. 78(5)", "Hours of Service — ELD repair deadline",
            "“A motor carrier shall, within 14 days after the day on which it was notified of an ELD malfunction code by the driver or otherwise became aware of it, or at the latest, upon return of the driver to the home terminal from a planned trip if that return exceeds the 14-day period, repair or replace the ELD.”",
            "A broken ELD is repaired or replaced within 14 days of the company learning about it.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc9_78_6, "NSC 9 s. 78(6)", "Hours of Service — ELD malfunction register retention", null,
            "The record of each ELD malfunction and its repair is kept for 6 months after the repair or replacement.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc9_81_2, "NSC 9 s. 81(2)", "Hours of Service — exempt time records", null,
            "When a driver works under an exemption (such as the 160 km radius), the carrier keeps the time records that prove it for 6 months.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc9_85_1, "NSC 9 s. 85(1)", "Hours of Service — driver forwards RODS",
            "“(1) A driver shall, within 20 days after completing a record of duty status, forward the record of duty status and supporting documents to the home terminal and the motor carrier shall ensure that the driver does so.”",
            "Drivers hand in each day's log and its supporting papers within 20 days, and the company makes sure they do.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc9_85_3, "NSC 9 s. 85(3)", "Hours of Service — carrier files and retains RODS",
            "“(3) The motor carrier shall: (a) deposit the records of duty status and the supporting documents relating to those records at its principal place of business within 30 days after receiving them; and (b) keep them in chronological order for each driver or unidentified driver profile file for a period of at least 6 months after the day on which they are received.”",
            "The company files the logs at its main office within 30 days of getting them and keeps them in date order, per driver, for at least 6 months.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc9_86, "NSC 9 s. 86(1)-(2)", "Hours of Service — one log per day; no falsification",
            "“(1) No motor carrier shall request, require or allow a driver to keep and no driver shall keep more than one record of duty status in respect of any day. (2) No motor carrier shall request, require or allow any person to enter and no person shall enter inaccurate information in a record of duty status or falsify, mutilate, obscure, alter, delete, destroy or deface the records or supporting documents.”",
            "One log per day, and nobody changes, hides or destroys a log or its supporting documents.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc9_87, "NSC 9 s. 87", "Hours of Service — carrier monitoring and remedial action",
            "“(1) A motor carrier shall monitor the compliance of each driver with this Standard. (2) A motor carrier that determines that there has been non-compliance with this Standard shall take immediate remedial action and record the dates on which the non-compliance occurred, and the action taken.”",
            "The company checks every driver's hours, and when it finds a violation it acts right away and writes down what happened and what it did.",
            Nsc9Url),
        Nsc(BasisKeys.Nsc10, "NSC Standard 10 (Jun 2013)", "Cargo Securement", null,
            "The national cargo securement standard, adopted in Manitoba by M.R. 37/2005.",
            Nsc10Url),
        Nsc(BasisKeys.Nsc10_Part1_Div2, "NSC 10 Part 1, Division 2", "Cargo Securement — general requirement",
            "“Cargo transported by a vehicle shall be contained, immobilized or secured so that it cannot (a) leak, spill, blow off, fall from, fall through or otherwise be dislodged from the vehicle, or …”",
            "Whatever we carry must be held so it cannot leak, spill, blow away or fall off.",
            Nsc10Url),
        Nsc(BasisKeys.Nsc10_Tiedowns, "NSC 10 ss. 4(2), 10(2), 11(4)", "Cargo Securement — tiedown condition, strength and marking",
            "“[s. 4(2)] … shall be in proper working order … shall have no knots, damaged or weakened components that will adversely affect their performance … [s. 10(2)] … shall not be less than 50% of the weight of the article … [s. 11(4)] A person shall not use a tiedown or a component of a tiedown to secure cargo to a vehicle unless … it is marked by the manufacturer with respect to its working load limit.”",
            "Straps must be undamaged and unknotted, strong enough for half the load's weight together, and marked with their working load limit.",
            Nsc10Url),
        Nsc(BasisKeys.Nsc11, "NSC Standard 11 (Jan 2020)", "Commercial Vehicle Maintenance and Periodic Inspection", null,
            "The national maintenance and periodic inspection standard: Part A is the carrier's maintenance program, Part B the periodic inspection criteria.",
            Nsc11Url),
        Nsc(BasisKeys.Nsc11_PartA, "NSC 11 Part A", "Maintenance — a system of preventive inspection, maintenance and repair",
            "“Every operator must have a system to inspect, maintain and repair each of the owned or leased vehicles at regular intervals. … Each carrier must establish a system of preventative vehicle inspection, maintenance and repair … Vehicle records must be kept for at least two years at the principal place of business.”",
            "The company runs a written preventive maintenance program for every vehicle and keeps the records at the main office for at least two years.",
            Nsc11Url),
        Nsc(BasisKeys.Nsc11_PartA_1_c, "NSC 11 Part A s. 1(c)", "Maintenance — record retention after a vehicle leaves",
            "“… for a period of at least two years and for six months after the vehicle leaves the motor carrier's control.”",
            "Maintenance records are kept two years, and for six months after the vehicle is sold or returned — whichever is later.",
            Nsc11Url),
        Nsc(BasisKeys.Nsc12, "NSC Standard 12", "CVSA On-Road Inspections", null,
            "The roadside inspection program (CVSA). A roadside report and any repair certification are kept two years. CCMTA publishes no PDF; the CVSA Out-of-Service Criteria are purchase-only.",
            Nsc12Url),
        Nsc(BasisKeys.Nsc13, "NSC Standard 13 (Mar 2009)", "Trip Inspection",
            "“The daily vehicle trip inspection standard is intended to ensure early identification of vehicle problems and defects …”",
            "The daily walk-around exists to catch problems before they become breakdowns or collisions.",
            Nsc13Url),
        Nsc(BasisKeys.Nsc13_4_b, "NSC 13 s. 4(b)", "Trip Inspection — buses every 24 hours (Schedule 2)", null,
            "A bus is inspected against Schedule 2 at least once every 24 hours.",
            Nsc13Url),
        Nsc(BasisKeys.Nsc13_13, "NSC 13 s. 13", "Trip Inspection — major defects",
            "“when a major defect is present on the vehicle.”",
            "No carrier may permit, and no driver may drive, a vehicle with a major defect.",
            Nsc13Url),
        Nsc(BasisKeys.Nsc13_14, "NSC 13 s. 14", "Trip Inspection — defects corrected",
            "“[s. 14] Motor carriers shall ensure that all previously reported vehicle defects are corrected …”",
            "Anything a driver reports gets fixed — the company has to make sure of it.",
            Nsc13Url),
        Nsc(BasisKeys.Nsc13_15, "NSC 13 s. 15", "Trip Inspection — driver forwards reports", null,
            "The driver forwards each inspection report to the carrier within 20 calendar days.",
            Nsc13Url),
        Nsc(BasisKeys.Nsc13_16, "NSC 13 s. 16", "Trip Inspection — retention",
            "“[s. 16] Carriers shall retain the original copy of each vehicle inspection report and certification of repairs …”",
            "The company keeps the original of every inspection report and repair certification for at least six months.",
            Nsc13Url),
        Nsc(BasisKeys.Nsc14, "NSC Standard 14 (Aug 2009)", "Safety Rating",
            "“[Introduction] … establishes the motor carrier safety rating framework by which each jurisdiction shall assess … [Part C, s. 5 — Satisfactory] … has a motor carrier profile that demonstrates safe operation … has passed a facility audit.”",
            "How carriers are rated. 'Satisfactory' means a clean profile and a passed facility audit.",
            Nsc14Url),
        Nsc(BasisKeys.Nsc15, "NSC Standard 15 (Dec 2003)", "Facility Audits",
            "“[s. 1] The purpose of the National Safety Code (NSC) Facility Audit is to monitor carriers for compliance with all applicable highway safety regulations … [s. 3(c)] … shall be kept, or made available, at the carrier's main place of business … [s. 3(d)(i)] … shall be made available for inspection by duly authorized inspectors during normal business hours”",
            "An auditor can visit the main office in business hours and must be able to see every required record there.",
            Nsc15Url),

        // ---- Guidance ------------------------------------------------------------------------------
        Guidance(BasisKeys.MtiSafetyMonitoring, RegulatoryInstrument.ManitobaGuidance, Mb, "MTI Motor Carrier Division — Safety Monitoring", "Safety Monitoring hub (SFC, carrier profile; 204-945-5322)",
            "The province's hub page for carrier safety: SFC, carrier profile and audits, with the Motor Carrier Division's number.",
            "https://www.gov.mb.ca/mti/mcd/safety_monitoring/index.html"),
        Guidance(BasisKeys.MtiSfc, RegulatoryInstrument.ManitobaGuidance, Mb, "MTI — Safety Fitness Certificates", "Safety Fitness Certificates (apply/renew/ratings/insuring)",
            "How to apply for, renew and insure the safety fitness certificate, and what the ratings mean.",
            "https://www.gov.mb.ca/mti/mcd/safety_monitoring/sfc/index.html"),
        Guidance(BasisKeys.MtiNewCarrier, RegulatoryInstrument.ManitobaGuidance, Mb, "MTI — New carriers: Safety Fitness Certificate", "New safety fitness certificate applicants (NET course within 180 days before designation; $2,000,000 liability for regulated passenger vehicles carried for compensation; safety plan submitted for review; first SFC valid 1 year)",
