        Plan(BasisKeys.Plan5_3, "5.3", "Periodic mandatory vehicle inspection",
            "Each bus passes a PMVI every 6 months, aligned to its plate renewal; the certificate is kept until superseded and copies for 2 years."),
        Plan(BasisKeys.Plan5_4, "5.4", "Trip inspection",
            "A Schedule-2 inspection every 24 hours before the first trip, reported on NL-VM-03; major defects ground the vehicle."),
        Plan(BasisKeys.Plan5_6, "5.6", "Vehicle identification",
